function streak(){let d=new Date(),n=0;if(!state.daily[d.toLocaleDateString('en-CA')])d.setDate(d.getDate()-1);while(state.daily[d.toLocaleDateString('en-CA')]){n++;d.setDate(d.getDate()-1)}return n}
function render(){const nav=[['home','home','Tổng quan'],['study','cards','Bài học & thẻ'],['review','review','Ôn tập'],['garden','garden','Khu vườn'],['collection','book','Sổ từ vựng']];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><svg viewBox="0 0 40 46" fill="none"><path d="M20 40V22" stroke="#285b45" stroke-width="3"/><path d="M20 29C3 29 3 12 3 12s19-2 17 17Z" fill="#285b45"/><path d="M21 21C19 4 36 2 36 2s6 18-15 19Z" fill="#96b578"/></svg><div>mầm<small>grow your words</small></div></div><nav class="nav">${nav.map(([p,i,t])=>`<button data-nav="${p}" class="${page===p?'active':''}">${icon(i)}${t}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note"><span>🌿</span><b>Chậm một chút cũng được.</b>Mỗi từ mới là một chiếc lá.<br>Cứ học, rồi vườn sẽ xanh.</div><div class="profile"><div class="avatar">🧑🏻‍🌾</div><div>Người gieo mầm<small>Cấp ${1+Math.floor(state.xp/100)} · ${state.xp} XP</small></div></div></div></aside><main class="main"><header class="topbar"><span>Không gian học tập <span style="margin:0 8px">/</span> <b>${nav.find(n=>n[0]===page)[2]}</b></span><div class="resources"><span class="pill warm">☀ ${streak()} <span>ngày</span></span><span class="pill">💧 ${state.water}</span></div></header><div id="content"></div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));if(page==='home')home();if(page==='study')study();if(page==='review')review();if(page==='garden')garden();if(page==='collection')collection()}
function go(p){page=p;if(p==='study')startStudy();if(p==='review'){reviewDeck=-1;startReview()};render();window.scrollTo(0,0)}
function deckCards(){return lessonDecks().map((d,i)=>{const total=lessonWords().filter(w=>w.deck===i).length;const n=lessonWords().filter(w=>w.deck===i&&state.learned[w.id]).length;return `<button class="deck" data-deck="${i}"><div class="deck-art">${d.icon}<small>${currentLesson().name.toUpperCase()}</small></div><b>${d.name}</b><p>${d.sub} · ${total} từ</p><div class="track"><i style="width:${n/total*100}%"></i></div><div class="deck-footer"><span>${n}/${total} từ đã học</span><span>→</span></div></button>`}).join('')}
function baseHome(){$('#content').innerHTML=`<div class="welcome"><div><div class="eyebrow">MỘT NGÀY MỚI, MỘT MẦM XANH</div><h1>Chào bạn, cùng gieo từ mới nhé 🌱</h1><p>Mỗi chút chăm chỉ hôm nay, một khu vườn xanh ngày mai.</p></div><span class="date">${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</span></div><div class="columns"><div><section class="hero"><div class="hero-content"><div class="eyebrow">KHU VƯỜN CỦA BẠN</div><h2>Gieo một từ nhỏ.<br>Nuôi một ước mơ.</h2><p>Học thêm một từ tiếng Trung,<br>để khu vườn lớn thêm một chút.</p><button class="primary" id="start">Bắt đầu gieo từ <span>↗</span></button></div><div class="hero-art">${gardenSVG()}</div><div class="floating-label">✦ ${plants[state.plant].name} · Cấp ${1+Math.floor(state.xp/100)}</div></section><div class="stats"><div class="stat"><span class="stat-icon">🍃</span><div><strong>${lessonWords().filter(w=>state.learned[w.id]).length}</strong><small>Từ đã gieo</small></div></div><div class="stat"><span class="stat-icon">🪴</span><div><strong>${state.owned.length}</strong><small>Cây trong vườn</small></div></div><div class="stat"><span class="stat-icon">✨</span><div><strong>${state.xp}</strong><small>Điểm tích lũy</small></div></div></div><div class="section-title"><h2>${currentLesson().name} · Chọn cụm từ vựng</h2><button class="text-button" id="all">Khám phá từ vựng ↗</button></div><div class="decks">${deckCards()}</div></div><aside class="right-column"><section class="panel"><div class="goal-head"><h3>Một chút mỗi ngày</h3><span class="tag">MỤC TIÊU</span></div><p>10 lượt học cho một ngày xanh hơn.</p><div class="goal-ring" style="--progress:${Math.min(100,daily()/10*100)}%"><div><strong>${daily()}<span style="font-size:14px;color:#a6b099"> / 10</span></strong><small>lượt học hôm nay</small></div></div><div class="goal-foot">${daily()>=10?'✦ Bạn đã hoàn thành mục tiêu hôm nay!':'✧ Từng bước nhỏ đều đáng quý'}</div></section><section class="panel review-panel"><div class="icon-box">↻</div><h3>Gặp lại để nhớ lâu</h3><p>${due().length?`Có <b>${due().length} từ</b> đang đợi bạn ôn lại.`:'Ôn lại những từ đã gieo để nhớ lâu hơn.'}<br>Trả lời đúng, nhận thêm nước tưới!</p><button class="secondary" id="review">Ôn tập ngay <span>→</span></button></section><section class="panel quote"><div class="han">慢慢来</div><p>màn man lái · Cứ từ từ thôi</p><small>Điều tốt đẹp cần thời gian để lớn.</small></section></aside></div><div class="bottom-note">Gieo chữ hôm nay, nở hoa ngày mai. 一起学习，一起成长。</div>`;$('#start').onclick=()=>go('study');$('#review').onclick=()=>go('review');$('#all').onclick=()=>go('collection');bindDecks()}
function bindDecks(){document.querySelectorAll('[data-deck]').forEach(b=>b.onclick=()=>{page='study';startStudy(+b.dataset.deck);render()})}
function startStudy(deck=-1){let pool=lessonWords().filter(w=>deck<0||w.deck===deck);pool.sort((a,b)=>Number(!!state.learned[a.id])-Number(!!state.learned[b.id]));session={type:'study',items:pool,index:0,flipped:false,showPinyin:false,done:0,deck}}
function speak(w){if(!('speechSynthesis'in window)){toast('Trình duyệt này chưa hỗ trợ đọc phát âm.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(w.han);u.lang='zh-CN';u.rate=.75;const v=speechSynthesis.getVoices().find(v=>v.lang.startsWith('zh'));if(v)u.voice=v;speechSynthesis.speak(u)}
function reward(w,quality){const old=state.learned[w.id]||{level:0};const level=quality?Math.min(5,old.level+1):0;state.learned[w.id]={level,due:Date.now()+(quality?[1,1,3,7,14,30][level]*86400000:600000)};state.water+=quality?5:1;state.xp+=quality?10:2;state.daily[day()]=daily()+1;save()}
function baseStudy(){if(!session||session.type!=='study')startStudy();const s=session,w=s.items[s.index];if(!w){finish('Mỗi từ mới, một mầm xanh.',`Bạn đã hoàn thành ${s.items.length} thẻ và nhận ${s.done} giọt nước.`,false);return}$('#content').innerHTML=`<div class="page-head"><div class="eyebrow">GIEO TỪ MỚI</div><h1>Một thẻ nhỏ, một bước tiến.</h1><p>Nhớ nghĩa trước khi lật thẻ. Hãy thành thật với trí nhớ của mình nhé.</p></div><div class="study-shell"><div class="study-top"><span>${s.deck<0?`${currentLesson().name} · Toàn bộ ${lessonWords().length} từ`:lessonDecks()[s.deck].name}</span><span>${s.index+1} / ${s.items.length}</span></div><div class="track" style="margin-bottom:22px"><i style="width:${s.index/s.items.length*100}%"></i></div><div id="flip" class="flashcard" role="button" tabindex="0" aria-label="Lật flashcard"><span class="eyebrow">${s.flipped?'CÙNG GHI NHỚ NHÉ':'BẠN CÓ NHỚ TỪ NÀY?'}</span><div class="han ${w.han.length>3?'long-han':''}">${w.han}</div><div class="pinyin-slot" id="card-pinyin">${s.flipped||s.showPinyin?`<div class="pinyin">${w.py}</div>`:''}</div>${!s.flipped?`<button id="toggle-pinyin" class="pinyin-toggle" aria-expanded="${s.showPinyin}" aria-controls="card-pinyin">${s.showPinyin?'Ẩn pinyin':'Hiện pinyin'} <span>◉</span></button>`:''}${s.flipped?`${w.pos?`${w.pos?`${w.pos?`<span class="tag">${w.pos}</span>`:""}`:""}`:""}<div class="meaning">${w.vi}</div>${w.exampleSource==='supplement'?'<div class="tag" style="margin:8px 0">Ví dụ &amp; cụm từ bổ sung</div>':''}<div class="example">${w.ex}<br>${w.exPy}<br>${w.tr}</div><div class="collocations">${w.collocations.map(c=>`<span>${c}</span>`).join('')}</div>`:''}<div class="hint">↻ ${s.flipped?'Nhấn để xem mặt trước':'Chạm thẻ để khám phá nghĩa'}</div></div><div style="text-align:center;margin-top:16px"><button class="speaker" id="speak" aria-label="Nghe phát âm">♫</button><span style="font-size:10px;color:#839378;margin-left:8px">Nghe phát âm</span></div><div class="study-actions">${s.flipped?'<button class="secondary" id="again">Cần ôn thêm · +1 💧</button><button class="primary" id="remember">Đã nhớ rồi · +5 💧</button>':'<button class="primary" id="reveal">Lật thẻ ↻</button>'}</div></div>`;$('#flip').onclick=()=>{s.flipped=!s.flipped;study()};$('#flip').onkeydown=e=>{if(e.target!==e.currentTarget)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();s.flipped=!s.flipped;study()}};if($('#toggle-pinyin'))$('#toggle-pinyin').onclick=e=>{e.stopPropagation();s.showPinyin=!s.showPinyin;study()};$('#speak').onclick=()=>speak(w);if($('#reveal'))$('#reveal').onclick=()=>{s.flipped=true;study()};if(s.flipped){const next=q=>{reward(w,q);s.done+=q?5:1;s.index++;s.flipped=false;s.showPinyin=false;render()};$('#again').onclick=()=>next(false);$('#remember').onclick=()=>next(true)}}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function startReview(deck=reviewDeck){reviewDeck=deck;const scope=lessonWords().filter(w=>deck<0||w.deck===deck);const learned=scope.filter(w=>state.learned[w.id]);const ready=scope.filter(w=>state.learned[w.id]&&state.learned[w.id].due<=Date.now());const pool=ready.length?ready:learned.length?learned:scope;session={type:'review',items:shuffle(pool).slice(0,8),index:0,score:0,water:0,answer:null,options:null,practice:!learned.length}}
function baseReview(){if(!session||session.type!=='review')startReview();const s=session,w=s.items[s.index];if(!w){finish('Khu vườn lại xanh thêm!',`Bạn trả lời đúng ${s.score}/${s.items.length} câu và nhận ${s.water} giọt nước. Những từ chưa nhớ sẽ được nhắc lại sau 10 phút.`,true);return}if(!s.options)s.options=shuffle([w,...shuffle(lessonWords().filter(x=>x.id!==w.id)).slice(0,3)]);$('#content').innerHTML=`<div class="page-head"><div class="eyebrow">TƯỚI LẠI KÝ ỨC</div><h1>Gặp lại một người bạn cũ.</h1><p>${s.practice?'Bắt đầu với bài ôn thử từ vựng cơ bản.':'Ưu tiên từ đến hạn; nếu chưa có từ đến hạn, cùng luyện lại các từ đã học.'}</p></div><div class="study-shell"><div class="study-top"><span>Chọn nghĩa tiếng Việt đúng</span><span>${s.index+1} / ${s.items.length} · ${s.score} đúng</span></div><section class="quiz-card"><div class="eyebrow">TỪ NÀY CÓ NGHĨA LÀ GÌ?</div><div class="han ${w.han.length>3?'long-han':''}">${w.han}</div><details class="quiz-pinyin"><summary>Hiện pinyin</summary><div class="pinyin">${w.py}</div></details><button class="speaker" id="speak" aria-label="Nghe phát âm">♫</button><div class="answers">${s.options.map(o=>`<button class="answer ${s.answer!==null?(o.id===w.id?'correct':o.id===s.answer?'wrong':''):''}" data-answer="${o.id}" ${s.answer!==null?'disabled':''}>${o.vi}</button>`).join('')}</div><div class="feedback" role="status">${s.answer!==null?(s.answer===w.id?'🌿 Chính xác! +5 giọt nước':`Đáp án đúng: ${w.vi}. Gặp lại sớm để nhớ hơn nhé.`):''}</div>${s.answer!==null?'<button id="next" class="primary">Tiếp tục →</button>':''}</section></div>`;$('#speak').onclick=()=>speak(w);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(s.answer!==null)return;s.answer=b.dataset.answer;const correct=s.answer===w.id;if(correct)s.score++;s.water+=correct?5:1;reward(w,correct);render()});if($('#next'))$('#next').onclick=()=>{s.index++;s.answer=null;s.options=null;review()}}
function finish(title,desc,quiz){$('#content').innerHTML=`<div class="study-shell finish"><div class="big">${quiz?'🌻':'🌱'}</div><div class="eyebrow">BẠN ĐÃ LÀM RẤT TỐT</div><h2>${title}</h2><p>${desc}</p><p>Mục tiêu hôm nay: <b>${daily()} / 10 lượt học</b></p><button class="primary" id="visit">Thăm khu vườn →</button><button class="secondary" id="more">${quiz?'Ôn thêm một lượt':'Gieo thêm từ mới'}</button></div>`;$('#visit').onclick=()=>go('garden');$('#more').onclick=()=>go(quiz?'review':'study')}
function garden(){$('#content').innerHTML=`<div class="page-head"><div class="eyebrow">CHÚT XANH CỦA RIÊNG BẠN</div><h1>Khu vườn bình yên.</h1><p>Mỗi câu trả lời đúng mang về 5 giọt nước. Dùng nước để gieo những loài cây mới.</p></div><div class="garden-stage">${gardenSVG(true)}<div style="margin-top:-24px;padding-bottom:20px"><span class="pill" style="display:inline-flex">${plants[state.plant].icon} ${plants[state.plant].name} · Cấp ${1+Math.floor(state.xp/100)}</span></div></div><div class="section-title" style="margin-top:30px"><h2>Gieo thêm niềm vui</h2><span style="font-size:12px">💧 ${state.water} giọt nước</span></div><div class="plant-grid">${plants.map((p,i)=>`<div class="plant-card"><div class="plant-emoji">${p.icon}</div><h3>${p.name}</h3><p>${p.desc}</p><button class="${i===state.plant?'secondary':'primary'}" data-plant="${i}" ${i===state.plant||(!state.owned.includes(i)&&state.water<p.cost)?'disabled':''}>${i===state.plant?'Đang trong vườn':state.owned.includes(i)?'Đặt vào vườn':`Gieo cây · ${p.cost} 💧`}</button></div>`).join('')}</div>`;document.querySelectorAll('[data-plant]').forEach(b=>b.onclick=()=>{const i=+b.dataset.plant;if(!state.owned.includes(i)){if(state.water<plants[i].cost)return;state.water-=plants[i].cost;state.owned.push(i)}state.plant=i;save();render();toast('Khu vườn đã có diện mạo mới! 🌿')})}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function baseCollection(){$('#content').innerHTML=`<div class="page-head"><div class="eyebrow">NHỮNG CHIẾC LÁ TRI THỨC</div><h1>Sổ từ vựng.</h1><p>${lessonWords().length} từ của ${currentLesson().name}, chia thành ${lessonDecks().length} cụm từ vựng. Chọn một từ để nghe phát âm.</p></div><input id="search" class="search" placeholder="Tìm chữ Hán, pinyin hoặc nghĩa tiếng Việt…" aria-label="Tìm từ vựng" value="${escapeHtml(query)}"><div class="filters"><button data-filter="-1" class="${filter===-1?'active':''}">Cả bài · ${lessonWords().length}</button>${lessonDecks().map((d,i)=>`<button data-filter="${i}" class="${filter===i?'active':''}">${d.icon} ${d.sub}</button>`).join('')}</div><div class="collection-grid" id="word-list"></div>`;const list=()=>{const q=query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const found=lessonWords().filter(w=>(filter<0||w.deck===filter)&&[w.han,w.py,w.vi].join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));$('#word-list').innerHTML=found.length?found.map(w=>`<div class="word-row"><div style="display:flex;justify-content:space-between;align-items:center"><div><span class="han">${w.han}</span><small>${w.py}</small></div><button data-sound="${w.id}" class="speaker" aria-label="Nghe ${w.han}">♫</button></div><p>${w.vi}</p><span class="tag">${state.learned[w.id]?'🌿 Đã gieo':'Hạt giống mới'}</span></div>`).join(''):'<p>Chưa tìm thấy từ phù hợp.</p>';document.querySelectorAll('[data-sound]').forEach(b=>b.onclick=()=>speak(words.find(w=>w.id===b.dataset.sound)))};$('#search').oninput=e=>{query=e.target.value;list()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=+b.dataset.filter;collection()});list()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}render();

function lessonHeader(){if(page==='garden')return;const l=lessons.find(x=>x.id===selectedLesson);const head=document.createElement('section');head.className='lesson-banner';head.innerHTML=`<div><span class="eyebrow">GIÁO TRÌNH CỦA BẠN · ${l.level}</span><h2>${l.name} · <span lang="zh-CN">${l.title}</span></h2><p>${l.translation}</p></div><label>Chọn bài học<select id="lesson-select" aria-label="Chọn bài học">${lessons.map(x=>`<option value="${x.id}" ${x.id===selectedLesson?'selected':''}>${x.name} · ${x.level} · ${words.filter(w=>w.lesson===x.id).length} từ</option>`).join('')}</select></label>`;document.querySelector('#content').prepend(head);document.querySelector('#lesson-select').onchange=e=>{selectedLesson=e.target.value;state.lastLesson=selectedLesson;save();session=null;filter=-1;query='';reviewDeck=-1;render()};if(page==='study'||page==='review'){const bar=document.createElement('div');bar.className='lesson-controls';const active=page==='study'?session.deck:reviewDeck;bar.innerHTML=`<label>Phạm vi ${page==='study'?'học':'ôn tập'}<select id="group-select"><option value="-1">Cả bài · ${lessonWords().length} từ</option>${lessonDecks().map((d,i)=>`<option value="${i}" ${i===active?'selected':''}>${d.name} · ${lessonWords().filter(w=>w.deck===i).length} từ</option>`).join('')}</select></label><button class="secondary" id="switch-mode">${page==='study'?'Ôn tập cụm này ↗':'Học flashcard cụm này ↗'}</button>`;head.after(bar);document.querySelector('#group-select').onchange=e=>{page==='study'?startStudy(+e.target.value):startReview(+e.target.value);render()};document.querySelector('#switch-mode').onclick=()=>{const d=page==='study'?session.deck:reviewDeck;if(page==='study'){page='review';startReview(d)}else{page='study';startStudy(d)}render()}}}

function home(){baseHome();lessonHeader()}
function study(){baseStudy();lessonHeader()}
function review(){baseReview();lessonHeader()}
function collection(){baseCollection();lessonHeader()}
